function openDeckBuilder(){modal('deck-builder',`<div class="deck-builder"><h2>COMPOSIZIONE MAZZI — 40 CARTE</h2><p>Ogni giocatore ha un pool indipendente di 67 carte. Scegli <b>38</b> carte tra le cinque categorie; le <b>2 Magicate</b> sono fisse.</p><div class="deck-build-columns"><section><h3>PLAYER 1</h3>${deckRows(0)}</section><section><h3>PLAYER 2</h3>${deckRows(1)}</section></div><p id="deckBuildError"></p><button id="confirmDeckBuild" class="primary">CONFERMA E GENERA I MAZZI</button></div>`);const totals=()=>[0,1].map(player=>DECK_CATEGORIES.filter(c=>c!=='MAGICATA').reduce((sum,c)=>sum+Number(document.querySelector(`[data-deck-player="${player}"][data-deck-category="${c}"]`).value||0),0));const refresh=()=>{const [one,two]=totals(),error=$('#deckBuildError');error.textContent=`Player 1: ${one}/38 · Player 2: ${two}/38`;error.className=one===38&&two===38?'ready':'warning'};document.querySelectorAll('[data-deck-player]').forEach(input=>input.oninput=refresh);refresh();$('#confirmDeckBuild').onclick=()=>{const totalsNow=totals();if(totalsNow.some(total=>total!==38)){alert('Ogni giocatore deve distribuire esattamente 38 carte, più 2 Magicate.');return}const choices=[0,1].map(player=>Object.fromEntries(DECK_CATEGORIES.map(category=>[category,Number(document.querySelector(`[data-deck-player="${player}"][data-deck-category="${category}"]`).value)])));s=newGame(C,Date.now(),choices);needsDeckSetup=false;selected=null;dismissModal();render()}}
