document.head.insertAdjacentHTML('beforeend',`<style>.deck-builder{max-width:860px}.deck-build-columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.deck-build-columns section{padding:12px;background:#0b1733;border:1px solid #375783}.deck-build-columns h3{margin-top:0}.deck-build-columns label{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;margin:7px 0}.deck-build-columns input{width:62px;padding:7px;background:#071126;color:#fff;border:1px solid #5781c6;font:inherit}.deck-builder .warning{color:#ff6573}.deck-builder .ready{color:#61f2a0}@media(max-width:600px){.deck-build-columns{grid-template-columns:1fr}.deck-builder h2{font-size:20px}.deck-builder p,.deck-build-columns label{font-size:14px}}</style>`);
let onlineSession;try{onlineSession=JSON.parse(localStorage.getItem('briscola-multiplayer-session')||'null')}catch{onlineSession=null}
const apiBase=String(C.MULTIPLAYER_API||'').replace(/\/$/,'');
const apiUrl=path=>`${apiBase}${path}`;
const inviteCode=new URLSearchParams(location.search).get('join')?.trim().toUpperCase();
async function onlineRequest(path,options={}){const response=await fetch(apiUrl(`/api/games/${onlineSession.code}${path}`),{...options,headers:{'content-type':'application/json',authorization:`Bearer ${onlineSession.accessToken}`,...options.headers}});const data=await response.json();if(!response.ok)throw Error(data.error||'Errore di rete');return data}
function onlineMode(){return!!onlineSession}
let waitingForOpponent=false,singleplayer=!!savedGame?.singleplayer,paused=true,cpuTimer=null,lastTurn=null,ending=false,actionPending=false,onlineRevision=0,expandedPlayer=null;
function canControl(){return !isPreparing(s)&&!actionPending&&s.winner===null&&!paused&&(onlineMode()?s.active===onlineSession.player:singleplayer&&s.active===0)}
function scheduleCPU(){clearTimeout(cpuTimer);if(singleplayer&&!onlineMode()&&!paused&&!isPreparing(s)&&s.active===1&&s.winner===null)cpuTimer=setTimeout(()=>{s=autoPlay(s,C);render()},850)}

function applyOnline(data){if(data.waiting){waitingForOpponent=true;$('#selected').textContent=`Stanza ${data.code}: in attesa di Player 2.`;return}const opponentJustJoined=waitingForOpponent&&onlineSession?.player===0;waitingForOpponent=false;paused=false;singleplayer=false;if(JSON.stringify(s)===JSON.stringify(data.state))return;s=data.state;s.players.forEach((p,i)=>p.name=`PLAYER ${i+1}`);render();$('#aiBtn').style.display='none';$('#onlineButton').textContent='MULTIPLAYER';$('#onlineButton').disabled=true;if(opponentJustJoined&&!isPreparing(s))modal('opponent-joined',`<div class="online-lobby"><h2>PLAYER 2 È ENTRATO</h2><p>La stanza è completa: la sfida può iniziare.</p><button id="startOnlineMatch" class="primary">OK, INIZIA SFIDA</button></div>`),$('#startOnlineMatch').onclick=()=>dismissModal()}
let onlinePoll;function startOnlinePolling(){if(!onlinePoll)onlinePoll=setInterval(syncOnline,5000)}
async function syncOnline(){if(!onlineSession||actionPending||ending)return;const session=onlineSession,revision=onlineRevision;try{const data=await onlineRequest('');if(session===onlineSession&&revision===onlineRevision&&!ending)applyOnline(data)}catch(error){console.warn(error.message);if(/è uscito dalla partita/.test(error.message))leaveOnline(false,error.message)}}
function onlineDeckRows(){return DECK_CATEGORIES.map(category=>{
  const fixed=category==='MAGICATA';
  const input=`<input data-online-category="${category}" aria-label="Numero di ${deckLabel[category]}" type="${fixed?'text':'number'}" inputmode="numeric" min="0" max="${DECK_LIMITS[category]}" ${fixed?'readonly':''} value="${DEFAULT_DECK_COUNTS[category]}">`;
  const step=direction=>`<button type="button" data-online-step="${direction}" data-online-for="${category}" aria-label="${direction<0?'Diminuisci':'Aumenta'} ${deckLabel[category]}">${direction<0?'−':'+'}</button>`;
  return `<label><span style="color:${CARD_POOL.find(c=>c.category===category).color}">${deckLabel[category]} <small>(${fixed?'2 obbligatorie su 10':DECK_LIMITS[category]+' disponibili'})</small></span><span class="deck-stepper ${fixed?'fixed-count':''}">${fixed?input:step(-1)+input+step(1)}</span></label>`;
}).join('')}
function deckTotal(){return DECK_CATEGORIES.filter(c=>c!=='MAGICATA').reduce((sum,c)=>sum+Number($(`[data-online-category="${c}"]`).value||0),0)}
function refreshDeck(){
  const total=deckTotal();
  $('#onlineDeckTotal').textContent=`Carte scelte ${total}/38`;
  $('#onlineDeckTotal').className=total===38?'ready':'warning';
  document.querySelectorAll('[data-online-step]').forEach(button=>{
    const input=$(`[data-online-category="${button.dataset.onlineFor}"]`),value=Number(input.value);
    button.disabled=Number(button.dataset.onlineStep)>0?(total>=38||value>=Number(input.max)):value<=0;
  });
  $('#confirmOnlineDeck').disabled=total!==38;
}
function editDeckCount(input){
  const other=DECK_CATEGORIES.filter(c=>c!=='MAGICATA'&&c!==input.dataset.onlineCategory).reduce((sum,c)=>sum+Number($(`[data-online-category="${c}"]`).value||0),0);
  input.value=input.dataset.onlineCategory==='MAGICATA'?2:Math.max(0,Math.min(Number(input.max),38-other,Math.trunc(Number(input.value)||0)));
  refreshDeck();
}
function openOnlineDeck(mode,code=''){
  modal('online-deck',`<div class="deck-builder online-deck-builder"><h2>IL TUO MAZZO — 40 CARTE</h2><p>Distribuisci <b>38</b> carte; le 2 Magicate sono fisse. ${mode==='single'?'La CPU riceverà un mazzo indipendente.':"L'altro giocatore comporrà il proprio mazzo separatamente."}</p><section class="deck-scroll" aria-label="Distribuzione carte">${onlineDeckRows()}</section><div class="deck-footer"><p id="onlineDeckTotal" aria-live="polite"></p><p id="onlineDeckError" role="alert"></p><div class="deck-actions"><button id="confirmOnlineDeck" class="primary">${mode==='single'?'INIZIA PARTITA':mode==='create'?'CREA STANZA':'ENTRA NELLA STANZA'}</button><button id="backLobby">INDIETRO</button></div></div></div>`);
  document.querySelectorAll('[data-online-category]').forEach(input=>input.oninput=()=>editDeckCount(input));
  refreshDeck();
  $('#confirmOnlineDeck').onclick=async()=>{if(deckTotal()!==38)return refreshDeck();const submit=$('#confirmOnlineDeck');if(submit.disabled)return;submit.disabled=true;try{const deckCounts=Object.fromEntries(DECK_CATEGORIES.map(category=>[category,Number(document.querySelector(`[data-online-category="${category}"]`).value)]));if(mode==='single'){s=newGame(C,Date.now(),[deckCounts,DEFAULT_DECK_COUNTS]);s.players[1].name='CPU';s.singleplayer=true;singleplayer=true;paused=false;needsDeckSetup=false;s=autoPrepare(s,C,1);dismissModal();render();return}const response=await fetch(mode==='create'?apiUrl('/api/games'):apiUrl(`/api/games/${code}/join`),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({deckCounts})}),data=await response.json();if(!response.ok)throw Error(data.error);onlineSession=data;$('#onlineButton').textContent='MULTIPLAYER';localStorage.setItem('briscola-multiplayer-session',JSON.stringify(data));startOnlinePolling();await syncOnline();$('#onlineButton').disabled=true;if(mode==='create'){const inviteUrl=new URL(location.href);inviteUrl.search='';inviteUrl.searchParams.set('join',data.code);modal('waiting',`<div class="online-lobby"><h2>STANZA CREATA</h2><p>Invia questo invito a Player 2:</p><input id="inviteLink" readonly value="${esc(inviteUrl.toString())}"><button id="inviteOnline" class="primary">INVITA VIA WHATSAPP</button><p>Oppure comunica il codice:</p><h1>${data.code}</h1><p>Quando entra l’avversario, entrambi preparerete la prima mano.</p><button id="cancelRoom">ANNULLA STANZA</button></div>`);$('#cancelRoom').onclick=()=>leaveOnline(true);$('#inviteOnline').onclick=async()=>{const text=`Sfida a BRISCOLA MAGICATA: entra nella mia stanza ${data.code}`;if(navigator.share){try{await navigator.share({title:'BRISCOLA MAGICATA',text,url:inviteUrl.toString()});return}catch(error){if(error.name==='AbortError')return}}location.href=`https://wa.me/?text=${encodeURIComponent(`${text} ${inviteUrl}`)}`}}else if(!isPreparing(s))dismissModal()}catch(error){$('#onlineDeckError').textContent=error.message;submit.disabled=false}}}
function openMultiplayerLobby(){modal('online',`<div class="online-lobby"><h2>PARTITA ONLINE</h2><p>Prima scegli il tuo mazzo da 40 carte; poi crea una stanza o entra con un codice.</p><button id="createOnline" class="primary">SCEGLI MAZZO E CREA</button><hr><label>Codice partita <input id="joinCode" maxlength="6" placeholder="ABC123"></label><button id="joinOnline">SCEGLI MAZZO ED ENTRA</button></div>`);$('#createOnline').onclick=()=>openOnlineDeck('create');$('#joinOnline').onclick=()=>{const code=$('#joinCode').value.trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code))return;openOnlineDeck('join',code)}}
function openOnlineLobby(){paused=true;clearTimeout(cpuTimer);modal('lobby',`<div class="online-lobby"><h2 class="lobby-title">BRISCOLA MAGICATA<span class="build-version">${APP_VERSION}</span></h2><button id="lobbyRules" aria-label="Istruzioni di gioco">?</button><p>Scegli come giocare.</p><button id="singleChoice" class="primary">${singleplayer?'CONTINUA A GIOCARE':'SINGLEPLAYER'}</button><button id="multiChoice">MULTIPLAYER</button></div>`);$('#singleChoice').onclick=()=>{if(singleplayer){paused=false;dismissModal();render()}else openOnlineDeck('single')};$('#multiChoice').onclick=openMultiplayerLobby;$('#lobbyRules').onclick=()=>modal('lobby-rules',richRules())}
async function exitAndReload(){if(ending)return;ending=true;clearTimeout(cpuTimer);clearInterval(onlinePoll);if(onlineMode()){try{await onlineRequest('/leave',{method:'POST'})}catch(error){console.warn(error.message)}}localStorage.removeItem('briscola-multiplayer-session');A.clear();location.replace(location.pathname)}
function gameNotice(message){modal('notice',`<div class="online-lobby"><h2>MESSAGGIO</h2><p>${esc(message)}</p><button id="closeNotice" class="primary">CHIUDI</button></div>`);$('#closeNotice').onclick=openOnlineLobby}
async function leaveOnline(notify=true,message=''){const session=onlineSession;if(session&&notify){try{await onlineRequest('/leave',{method:'POST'})}catch(error){console.warn(error.message)}}if(onlinePoll){clearInterval(onlinePoll);onlinePoll=null}onlineSession=null;singleplayer=false;paused=true;localStorage.removeItem('briscola-multiplayer-session');A.clear();s=newGame(C);selected=null;needsDeckSetup=true;render();if(message)gameNotice(message);else openOnlineLobby()}
async function leaveGame(){document.querySelector('header').classList.remove('menu-open');if(s.winner!==null||confirm('Uscire dalla partita?'))await exitAndReload()}
document.head.insertAdjacentHTML('beforeend',`<style>#onlineButton{font-size:20px}.online-lobby input{display:block;width:100%;padding:10px;margin:7px 0;background:#071126;color:#fff;border:1px solid #5781c6;font:18px monospace}.online-lobby hr{margin:18px 0;border-color:#375783}.online-lobby .warning{color:#ff6573}.online-deck-builder section{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;margin:16px 0}.online-deck-builder label{display:grid;grid-template-columns:1fr auto;align-items:center;gap:16px;padding:12px 14px;background:#0b1733;border:1px solid #375783;font-size:18px;line-height:1.3}.online-deck-builder label small{color:#9ebbe9}.online-deck-builder input{width:76px;padding:9px;background:#071126;color:#fff;border:1px solid #5781c6;font:inherit;text-align:center}.deck-stepper{display:grid;grid-template-columns:44px auto 44px;gap:6px;align-items:center}.deck-stepper button{min-height:42px;padding:0;background:#19376e;color:#fff;border:1px solid #5781c6;font:28px monospace}.deck-stepper button:disabled{opacity:.35}.online-deck-builder p{font-size:17px;line-height:1.45}@media(pointer:coarse){#onlineButton{display:block!important;order:0;min-width:44px;font-size:25px!important}.online-deck-builder label{font-size:28px;padding:16px}.online-deck-builder input{width:92px;font-size:28px}.deck-stepper{grid-template-columns:58px auto 58px}.deck-stepper button{min-height:58px;font-size:38px}.online-deck-builder p{font-size:28px}}</style>`);
