setTimeout(()=>{const localDoAct=doAct,localEndTurn=$('#endTurn').onclick;doAct=async action=>{if(!canControl())return;if(!onlineMode())return localDoAct(action);actionPending=true;onlineRevision++;try{const data=await onlineRequest('/action',{method:'POST',body:JSON.stringify({action})});actionPending=false;applyOnline(data)}catch(error){gameNotice(error.message)}finally{actionPending=false}};$('#endTurn').onclick=async()=>{if(!canControl())return;if(!onlineMode())return localEndTurn();actionPending=true;onlineRevision++;try{const data=await onlineRequest('/end-turn',{method:'POST'});actionPending=false;applyOnline(data)}catch(error){gameNotice(error.message)}finally{actionPending=false}};if(onlineSession){$('#onlineButton').disabled=true;syncOnline();startOnlinePolling()}else if(/^[A-Z0-9]{6}$/.test(inviteCode||''))openOnlineDeck('join',inviteCode);else openOnlineLobby();setTimeout(()=>{const baseOnlineRender=render;render=()=>{const hiddenHand=onlineMode()&&s.active!==onlineSession.player?s.players[s.active].hand:null;baseOnlineRender();if(hiddenHand){$('#hand').innerHTML=hiddenHand.map(()=>'<div class="card card-back" aria-label="Carta coperta"></div>').join('');$('#selected').textContent='In attesa che PLAYER '+(s.active+1)+' completi il turno.';$('#endTurn').disabled=true}}},0)},0);
function openDeckList(){const player=s.players[onlineMode()?onlineSession.player:0],list=[...player.hand,...player.deck,...player.discard].map(id=>byId(id)).filter(Boolean);modal('deck',`<div class="deck-list"><h2>IL TUO MAZZO</h2><p>${list.length}/40 carte. Il mazzo avversario resta segreto.</p>${DECK_CATEGORIES.map(category=>{const cards=list.filter(card=>card.category===category);return`<h4 style="color:${CARD_POOL.find(c=>c.category===category).color}">${deckLabel[category]} · ${cards.length}</h4><p>${cards.map(card=>`${gameIcon(card.category)} ${esc(card.name)}`).join(' · ')||'—'}</p>`}).join('')}</div>`)}
