function unitArt(name,cssClass='unit-art'){return `<span class="${cssClass} card-art" style="${spriteStyle(name)}" aria-hidden="true"></span>`}
function unitRows(p,type){
  const list=type==='shield'?p.shields:type==='virus'?p.viruses:p.drones;
  return list.map((item,index)=>`<button type="button" class="unit-row ${item.used?'used':''}" data-unit="${type}" data-owner="${p.id}" data-index="${index}"><span class="unit-label">${gameIcon(type)} ${esc(item.name)} ${type==='drone'?`${item.attack}/${item.hp}`:item.amount}</span>${unitArt(item.name)}</button>`).join('')||'<span>—</span>';
}
