document.addEventListener('click',e=>{if(e.target.closest('#rulesButton')){e.stopImmediatePropagation();modal('rules',richRules())}},true);
function localPlayerId(){return onlineSession?.player??0}
function canPrepare(){return isPreparing(s)&&!paused&&!actionPending&&!s.preparation.ready[localPlayerId()]}
function preparationCard(id){
  const p=s.players[localPlayerId()],card=byId(id),played=!p.hand.includes(id),blocked=dealsImmediateDamage(card);
  return `<button class="card card-art preparation-card ${blocked?'attack-blocked':''} ${played?'prepared':''}" data-card="${id}" style="--c:${card.color};${spriteStyle(card.name)}"><span>${gameIcon(card.category)}</span><i class="card-energy">${cardCost(s,card)} <em class="${p.energy>=cardCost(s,card)?'energy-ready':'energy-low'}">${gameIcon('ENERGIA')}</em></i><b>${esc(card.name)}</b>${blocked?`<small class="preparation-warning">${PREPARATION_WARNING}</small>`:played?'<small class="prepared-label">DISPOSTA</small>':''}</button>`;
}
function openPreparation(message=''){
  if(!isPreparing(s))return;
  const id=localPlayerId(),p=s.players[id],ready=s.preparation.ready[id];
  modal('preparation',`<section class="preparation-screen"><h2>PREPARA LA PRIMA MANO</h2><div class="preparation-hand"><div class="preparation-grid">${p.openingHand.map(preparationCard).join('')}</div></div><div class="preparation-energy">${gameIcon('ENERGIA')} ENERGIA ${p.energy}/${p.maxEnergy} · MOSSE ${s.preparation.movesUsed[id]}/${C.RULES.MOVES_PER_TURN+(s.temp.reducedMoves[id]||0)}</div><p class="preparation-help">Se hai le carte, prepara le tue difese e strategie, in questa fase non puoi fare danno. Premi INIZIA quando vuoi.</p><p class="preparation-status" role="status">${esc(message|| (ready?'In attesa che l’altro giocatore prema INIZIA.':s.preparation.ready[1-id]?'L’altro giocatore è pronto.':''))}</p><button id="readyPreparation" class="primary" ${ready?'disabled':''}>${ready?'IN ATTESA':'INIZIA'}</button></section>`);
  $('#readyPreparation').onclick=()=>finishPreparation();
}
async function playPreparationCard(action){
  if(!canPrepare())return;
  const id=localPlayerId();actionPending=true;onlineRevision++;
  try{
    if(onlineMode()){const data=await onlineRequest('/action',{method:'POST',body:JSON.stringify({action})});actionPending=false;applyOnline(data)}
    else{s=act(s,C,action,id);actionPending=false;render()}
    if(isPreparing(s))openPreparation();
  }catch(error){openPreparation(error.message)}finally{actionPending=false}
}
async function finishPreparation(){
  if(!canPrepare())return;
  actionPending=true;onlineRevision++;$('#readyPreparation').disabled=true;
  try{
    if(onlineMode()){const data=await onlineRequest('/ready',{method:'POST'});actionPending=false;applyOnline(data)}
    else{s=readyPreparation(s,C,0);actionPending=false;render()}
  }catch(error){openPreparation(error.message)}finally{actionPending=false}
}

function playerPanelContents(owner){const p=s.players[owner];return `<section class="player-panel"><h2>PLAYER ${owner+1}</h2><p id="expandedPlayerVitals">${gameIcon('INTEGRITA')} ${p.integrity}/${C.RULES.CORE_INTEGRITY} · ${gameIcon('ENERGIA')} ${p.energy}/${p.maxEnergy}</p><div class="expanded-units"><h3>SCUDI</h3>${unitRows(p,'shield')}<h3>VIRUS</h3>${unitRows(p,'virus')}<h3>DRONE</h3>${unitRows(p,'drone')}</div><button id="closePlayerPanel">CHIUDI</button></section>`}
function openPlayerPanel(owner){
  expandedPlayer=owner;modal('player-panel',playerPanelContents(owner),{side:owner===0?'left':'right'});
  $('#closePlayerPanel').onclick=dismissModal;
}
function arenaHud(){return s.players.map((p,i)=>`<div class="core-hud p${i+1}"><b>${esc((C.TEXT[`PLAYER_${i+1}`]||`PLAYER${i+1}`).replace(/\s/g,''))}</b>|<span title="${esc(C.TEXT.INTEGRITY)}" aria-label="${esc(C.TEXT.INTEGRITY)}"><em class="hud-heart">${gameIcon('INTEGRITA')}</em>${p.integrity}</span>|<span title="${esc(C.TEXT.ENERGY)}" aria-label="${esc(C.TEXT.ENERGY)}"><em class="hud-energy">${gameIcon('ENERGIA')}</em>${p.energy}</span>|</div>`).join('<span class="hud-divider" aria-hidden="true">◆</span>')}

function openUnitDetail(button){const owner=Number(button.dataset.owner),type=button.dataset.unit,list=type==='shield'?'shields':type==='virus'?'viruses':'drones',item=s.players[owner]?.[list]?.[Number(button.dataset.index)];if(!item)return;const remaining=C.RULES.MOVES_PER_TURN+(s.temp.reducedMoves[s.active]||0)-s.movesUsed;let body='',action='';if(type==='drone'){const usable=canControl()&&owner===s.active&&!item.used&&remaining>0;body=`<p><b>Drone persistente.</b> Resta sul tavolo e può attaccare una volta per turno.</p><p>Attacco <b>${item.attack}</b> · Integrità <b>${item.hp}</b>.</p>`;action=usable?`<p class="ready">Pronto: usa 1 mossa.</p><button class="primary" data-unit-use="${item.uid}">USA: ATTACCA</button>`:`<p class="warning">${owner!==s.active?'È un Drone dell’avversario.':item.used?'Ha già attaccato in questo turno.':remaining<=0?'Non hai più mosse disponibili.':'La partita è conclusa.'}</p>`}else if(type==='shield'){body=`<p><b>Scudo installato.</b> Assorbe i danni prima che raggiungano il Nucleo.</p><p>Protezione rimasta: <b>${item.amount}</b>.</p><p class="warning">È già attivo: non richiede azioni manuali.</p>`}else{body=`<p><b>Virus installato.</b> Si attiva automaticamente all’inizio del turno del suo proprietario.</p><p>Effetto previsto: <b>${item.amount} danni</b>.</p><p class="warning">È già attivo: non richiede azioni manuali.</p>`}modal('unit',`<div class="unit-detail" style="color:${type==='shield'?'#0fa7ef':type==='virus'?'#bf1014':'#ffed9a'}"><h2>${gameIcon(type)} ${esc(item.name)}</h2>${body}${action}</div>`,{art:item.name,onClose:expandedPlayer===null?null:()=>openPlayerPanel(owner)})}
function openCardPreview(cardId){
  const preparing=isPreparing(s),actor=preparing?localPlayerId():s.active,card=byId(cardId),action={type:'play',cardId,target:1-actor};
  const reason=(preparing?canPrepare():canControl())?legal(s,C,action,actor):'Attendi il tuo turno',usable=!reason;
  selected=null;
  modal(preparing?'preparation-card':'card-preview',`<div class="card-preview" style="--c:${card.color}"><div class="preview-art card-art" style="${spriteStyle(card.name)}"></div><span>${gameIcon(card.category)} ${card.category}</span><h2>${esc(card.name)}</h2><p class="cost ${cardCost(s,card)>s.players[actor].energy?'warning':''}">${cardCost(s,card)} ${gameIcon('ENERGIA')} Energia</p><p>${esc(card.description)}</p>${usable?`<button class="primary" data-play-card="${card.id}">GIOCA</button>`:`<p class="warning">Non giocabile: ${esc(preparing&&dealsImmediateDamage(card)?PREPARATION_WARNING:reason)}</p>`}</div>`);
}
document.addEventListener('click',e=>{const play=e.target.closest('[data-play-card]');if(play){e.stopImmediatePropagation();const card=byId(play.dataset.playCard),preparing=isPreparing(s),owner=preparing?localPlayerId():s.active,action={type:'play',cardId:card.id,target:1-owner};if((preparing?canPrepare():canControl())&&!legal(s,C,action,owner)){if(preparing){playPreparationCard(action);return}dismissModal();doAct(action)}return}const card=e.target.closest('[data-card]');if(card){e.stopImmediatePropagation();openCardPreview(card.dataset.card)}},true);
document.addEventListener('click',e=>{const use=e.target.closest('[data-unit-use]');if(use){e.stopImmediatePropagation();dismissModal();doAct({type:'attack',uid:use.dataset.unitUse});return}const unit=e.target.closest('[data-unit]');if(unit){e.stopImmediatePropagation();openUnitDetail(unit)}},true);
setTimeout(()=>{const baseRender=render;render=()=>{baseRender();updateMobileStatus();$('#briscolaBanner span').textContent=`BRISCOLA ATTIVA · ${s.briscola.name}`;$('#briscolaBanner b').textContent=`MOSSE ${s.movesUsed} / ${C.RULES.MOVES_PER_TURN+(s.temp.reducedMoves[s.active]||0)}`;$('#centerHud').innerHTML=arenaHud();};render()},0);
$('#menuButton').onclick=()=>document.querySelector('header').classList.toggle('menu-open');
$('#logButton').onclick=()=>modal('registro',`<div class="rules"><h2>Registro di Battaglia</h2><p>Qui trovi ogni azione già risolta, utile per riprendere una partita asincrona.</p><div id="modalLog">${s.history.map(x=>`<p><b>Turno ${x.turnId}</b> — ${esc(x.text).replaceAll('☢',gameIcon('RADIAZIONE'))}</p>`).join('')}</div></div>`);
// Quando la partita finisce, il pannello esito offre sempre una nuova partita immediata.
function richRules(){return`<div class="rules"><h2>Regole di BRISCOLA MAGICATA</h2><p><b>Scopo della partita.</b> Vinci in due modi: riduci l’<b>Integrità</b> del Nucleo avversario a zero, oppure inizia ${C.RULES.DOMINION_TURNS_TO_WIN} dei tuoi turni consecutivi con almeno ${C.RULES.DOMINION_THRESHOLD} punti <b>Dominio</b>. Non esiste un timer: la partita può proseguire per giorni.</p><h3>Preparazione della prima mano</h3><p>Prima della battaglia ciascun giocatore dispone fino a ${C.RULES.MOVES_PER_TURN} carte della prima mano, spendendo la propria Energia. Non sono consentiti attacchi dei Droni o danni immediati dei Laser. Virus e Radiazioni si preparano senza fare danno e si risolvono nei turni successivi. Premi <b>INIZIA</b> anche se non hai carte utilizzabili: la battaglia comincia soltanto quando entrambi sono pronti. Le due preparazioni valgono come i primi due turni; poi riprendono pesca, Energia ed effetti normali.</p><h3>1. Turni, Energia e mosse</h3><p>Nel tuo turno l’Energia torna al massimo attuale e peschi una carta. Puoi eseguire fino a ${C.RULES.MOVES_PER_TURN} mosse: giocare una carta, attivare un effetto o ordinare l’attacco di un Drone. Puoi terminare anche prima con <b>Fine Turno</b>; il turno termina automaticamente quando non restano azioni legali.</p><h3>2. Nucleo, Integrità e Scudi</h3><p>Il <b>Nucleo</b> è la Cittadella Orbitale del giocatore: parte con ${C.RULES.CORE_INTEGRITY} Integrità. Gli <b>Scudi</b> sono protezioni installate davanti al Nucleo: assorbono il danno in ordine, poi i Droni assorbono il danno con la propria Integrità; il residuo colpisce il Nucleo. Un Drone distrutto perde anche il Dominio prodotto. Alcuni Scudi hanno varianti speciali, ma tutti mostrano chiaramente la protezione rimasta.</p><h3>3. Drone</h3><p>I <b>Drone</b> sono unità meccaniche persistenti: restano sul tavolo e hanno Attacco/Integrità, ad esempio 2/3. Clicca un Drone disponibile per ordinargli un attacco al Nucleo nemico: conta come una mossa. Un Drone può attaccare una volta per turno; alcuni producono Dominio o hanno abilità difensive.</p><h3>4. Virus e Radiazione</h3><p>I <b>Virus</b> sono sabotaggi informatici installati sull’avversario. L’avversario vede un’anomalia, e il Virus si attiva automaticamente all’inizio del suo turno: nessuna risposta in tempo reale è richiesta. La <b>Radiazione</b> (${gameIcon('RADIAZIONE')}) è un danno persistente: ogni inizio turno infligge 1 danno e diminuisce di 1, fino a sparire.</p><h3>5. Laser, Briscola e Magicate</h3><p>I <b>Laser</b> infliggono danno immediato e costano Energia. La <b>Briscola</b> è una regola globale estratta periodicamente: vale per entrambi fino alla successiva. Le <b>Magicate</b> sono carte rare e potenti, con effetti insoliti ma sempre registrati nel Registro di Battaglia.</p><h3>6. Registro, Direttive e mazzo</h3><p>Il <b>Registro di Battaglia</b> racconta azioni, danni, scudi, Briscole ed effetti risolti, così puoi riprendere una partita asincrona senza dubbi. Le <b>Direttive</b> sono reazioni automatiche impostate in precedenza. Se il mazzo finisce, ogni pesca mancata causa danno crescente al proprietario.</p></div>`}
document.addEventListener('click',e=>{let b=e.target.closest('[data-modal="rules"]');if(b){e.stopImmediatePropagation();modal('rules',richRules())}},true);
function meter(label,v,max,color){return`<div class="meter"><label>${label} <b>${v}/${max}</b></label><i><em style="width:${Math.min(100,v/max*100)}%;background:${color}"></em></i></div>`}function player(p,enemy){return`<div class="area-title">${enemy?'AVVERSARIO':'TU'} · ${p.name}</div><div class="core"><b>◉ NUCLEO</b>${meter(gameIcon('INTEGRITA')+' '+C.TEXT.INTEGRITY,p.integrity,C.RULES.CORE_INTEGRITY,C.COLORS.INTEGRITY)}${meter(gameIcon('ENERGIA')+' '+C.TEXT.ENERGY,p.energy,p.maxEnergy,C.COLORS.ENERGY)}<div class="stats">◆ DOMINIO <b>${p.dominance}/${C.RULES.DOMINION_THRESHOLD}</b> · <span class="radiation-count" style="color:#4cdd4d">${gameIcon('RADIAZIONE')} ${p.radiation}</span></div></div><div class="units"><strong style="color:#0fa7ef">SCUDI</strong>${unitRows(p,'shield')}<strong style="color:#ffed9a">DRONE</strong>${unitRows(p,'drone')}<strong style="color:#bf1014">VIRUS</strong>${unitRows(p,'virus')}</div>`}
function render(){let p=s.players[s.active],o=s.players[1-s.active];for(const [selector,markup] of [['#opponent',player(s.players[1],true)],['#current',player(s.players[0],false)]]){const el=$(selector),top=el.scrollTop;if(el.innerHTML!==markup)el.innerHTML=markup;el.scrollTop=top}$('#turnBanner').textContent=`TURNO ${s.turnId} · ${p.name}`;$('#centerHud').innerHTML=`<div class="briscola"><small>BRISCOLA ATTIVA · ROUND ${s.round}</small><b>${s.briscola.icon} ${esc(s.briscola.name)}</b><span>${esc(s.briscola.description)}</span></div><div class="moves">MOSSE <b>${s.movesUsed} / ${C.RULES.MOVES_PER_TURN+(s.temp.reducedMoves[s.active]||0)}</b></div>`;$('#summary').innerHTML=esc(s.history[0]?.text||'').replaceAll('☢',gameIcon('RADIAZIONE'));$('#log').innerHTML=s.history.slice(0,18).map(x=>`<p class="${x.type}"><small>T${x.turnId}</small> ${esc(x.text).replaceAll('☢',gameIcon('RADIAZIONE'))}</p>`).join('');$('#hand').innerHTML=p.hand.map(id=>{if(!onlineMode()&&s.active===1)return '<div class="card card-back" aria-label="Carta coperta"></div>';let c=byId(id);return`<button class="card card-art ${selected===id?'selected':''}" data-card="${id}" style="--c:${c.color};${spriteStyle(c.id==='hidden'?'hidden':c.name)}" title="${esc(c.description)}"><span>${gameIcon(c.category)}</span><i class="card-energy" aria-label="${cardCost(s,c)} Energia">${cardCost(s,c)} <em class="${p.energy>=cardCost(s,c)?'energy-ready':'energy-low'}">${gameIcon('ENERGIA')}</em></i><b>${esc(c.name)}</b></button>`}).join('');$('#selected').textContent=selected?`Carta selezionata: ${byId(selected).name}. Clicca di nuovo per giocarla contro l’avversario.`:'Seleziona una carta per leggere il tooltip e giocarla.';$('#endTurn').disabled=!canControl();$('#onlineButton').textContent=onlineMode()?'MULTIPLAYER':'SINGLEPLAYER';$('#onlineButton').disabled=onlineMode();R.update(s);if(singleplayer)A.save(s);if(lastTurn!==null&&lastTurn!==s.turnId){const toast=document.createElement('div');toast.className='turn-toast';toast.textContent='FINE TURNO';document.body.append(toast);setTimeout(()=>toast.remove(),1100)}lastTurn=s.turnId;scheduleCPU();
const modalKind=$('#modalRoot .modal')?.dataset.kind;
if(isPreparing(s)&&!paused&&modalKind!=='preparation-card')openPreparation();
else if(!isPreparing(s)&&['preparation','preparation-card'].includes(modalKind))dismissModal();
if(modalKind==='player-panel'&&expandedPlayer!==null){const p=s.players[expandedPlayer];$('#expandedPlayerVitals').innerHTML=`${gameIcon('INTEGRITA')} ${p.integrity}/${C.RULES.CORE_INTEGRITY} · ${gameIcon('ENERGIA')} ${p.energy}/${p.maxEnergy}`;const el=$('.expanded-units'),top=el.scrollTop;el.innerHTML=`<h3>SCUDI</h3>${unitRows(s.players[expandedPlayer],'shield')}<h3>VIRUS</h3>${unitRows(s.players[expandedPlayer],'virus')}<h3>DRONE</h3>${unitRows(s.players[expandedPlayer],'drone')}`;el.scrollTop=top}
if(s.winner!==null&&$('#modalRoot .modal')?.dataset.kind!=='fine')modal('fine',`<h2>${s.winner===(onlineSession?.player??0)?'VITTORIA':'SCONFITTA'}</h2><p>${s.players[s.winner].name} controlla il settore orbitale.</p>`)}
function doAct(a){if(!canControl())return;try{s=act(s,C,a);selected=null;render()}catch(e){alert(e.message)}}document.addEventListener('click',e=>{let c=e.target.closest('[data-card]');if(c){let id=c.dataset.card;if(selected===id)doAct({type:'play',cardId:id,target:1-s.active});else{selected=id;render()}return}let d=e.target.closest('[data-attack]');if(d)doAct({type:'attack',uid:d.dataset.attack});let m=e.target.dataset.modal;if(m)showModal(m)});$('#endTurn').onclick=()=>{if(!canControl())return;let remaining=C.RULES.MOVES_PER_TURN+(s.temp.reducedMoves[s.active]||0)-s.movesUsed;if(remaining>0&&!confirm(`Restano ${remaining} mosse. Confermi Fine Turno?`))return;s=endTurn(s,C);render()};$('#aiBtn').onclick=()=>{for(let i=0;i<C.RULES.MOVES_PER_TURN;i++)s=autoPlay(s,C);s=endTurn(s,C);render()};$('#resetBtn').onclick=leaveGame;
function dismissModal(){
  expandedPlayer=null;$('#modalRoot').innerHTML='';
  $('#app').inert=false;
}
function modal(kind,content,{art,onClose=null,side}={}){
  document.querySelector('header').classList.remove('menu-open');
  const locked=['preparation','lobby','lobby-rules','online','online-deck','waiting','opponent-joined'].includes(kind);
  const closeButton=(!locked&&kind!=='player-panel')||kind==='lobby-rules';
  $('#app').inert=true;
  $('#modalRoot').innerHTML=`<div class="modal" data-kind="${kind}" data-side="${side||''}" role="dialog" aria-modal="true"><article ${art?'class="unit-article"':''}>${art?unitArt(art,'unit-popup-art'):''}${content}${closeButton?'<button id="closeModal" class="modal-close-bottom">CHIUDI</button>':''}${kind==='online'?'<button id="backLobby">INDIETRO</button>':''}</article></div>`;
  const closeAction=()=>{if(kind==='fine')exitAndReload();else if(kind==='lobby-rules')openOnlineLobby();else if(kind==='preparation-card')openPreparation();else if(onClose)onClose();else dismissModal()};
  const close=$('#closeModal');if(close)close.onclick=closeAction;
  const back=$('#backLobby');if(back)back.onclick=openOnlineLobby;
  $('.modal').onclick=e=>{if(e.target!==e.currentTarget||locked)return;closeAction()};
}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('header nav')&&!e.target.closest('#menuButton'))document.querySelector('header').classList.remove('menu-open')});
function showModal(k){if(k==='rules')modal(k,`<h2>REGOLE</h2><p>Riduci l’Integrità avversaria a zero o mantieni ${C.RULES.DOMINION_THRESHOLD} Dominio per ${C.RULES.DOMINION_TURNS_TO_WIN} turni propri. Ogni turno hai ${C.RULES.MOVES_PER_TURN} mosse e l’Energia si ripristina. Scudi assorbono danni; Drone attaccano; Virus e Radiazione colpiscono nel turno futuro; la Briscola cambia le regole globali.</p><h3>Direttive</h3><p>Sono reazioni automatiche già impostate: non richiedono che l’avversario sia connesso.</p>`);if(k==='tutorial')modal(k,`<h2>TUTORIAL RAPIDO</h2><ol><li>Scegli una carta dalla mano; cliccala di nuovo per usarla.</li><li>Usa Drone persistenti cliccandoli.</li><li>Controlla Energia e MOSSE, poi premi Fine Turno.</li><li>Leggi il Registro al centro per ricostruire una partita asincrona.</li></ol>`);if(k==='deck')modal(k,`<h2>DECK BUILDING</h2><p>Mazzi pronti: Bastione Orbitale e Piaga Rossa (30 carte, massimo ${C.RULES.MAX_MAGIFICATE} Magicate). Il pool contiene ${CARD_POOL.length} carte; in questa versione i mazzi pronti sono bilanciati e modificabili in <code>src/data/cards.js</code>.</p><button id="bast">USA BASTIONE</button> <button id="piaga">USA PIAGA ROSSA</button><div class="pool">${CARD_POOL.map(c=>`<span>${gameIcon(c.category)} ${esc(c.name)} (${c.cost})</span>`).join('')}</div>`);setTimeout(()=>{let b=$('#bast'),p=$('#piaga');if(b)b.onclick=()=>{s=newGame(C);s.players[0].deck=preset('BASTIONE ORBITALE');render();dismissModal()};if(p)p.onclick=()=>{s=newGame(C);s.players[0].deck=preset('PIAGA ROSSA');render();dismissModal()}},0)}render();

document.head.insertAdjacentHTML('beforeend',`<style>
#onlineButton{font-size:10px!important;min-width:0!important;padding:8px 5px!important}button:disabled{cursor:default;opacity:.55}
.card-art,.card-back{background-image:url('assets/images/cards/sprite-sheet.png')!important;background-size:1000% 700%!important;background-repeat:no-repeat!important}
.card-back{background-position:100% 100%!important}.card{position:relative;justify-content:space-between}.card>span,.card>b{position:relative;background:#050817cc;padding:3px;text-shadow:0 1px 3px #000}.card>span{font-size:20px!important}.card>b{width:100%;text-align:left}.card-preview{position:relative;isolation:isolate;overflow:hidden;text-align:left;min-height:250px}.preview-art{position:absolute;right:0;top:0;height:100%;aspect-ratio:120/187;z-index:-1;opacity:.65}.card-preview h2,.card-preview p,.card-preview>span{position:relative;text-shadow:0 1px 4px #000}.card-preview p{max-width:85%}
.modal-close-bottom{display:block;width:100%;margin-top:18px}.online-lobby>button{margin:8px 4px 8px 0}.mobile-player{overflow-anchor:none;scroll-behavior:auto}.turn-toast{position:fixed;z-index:30;top:45%;left:50%;transform:translate(-50%,-50%);padding:18px 30px;background:#0b1733ed;border:1px solid #8bd8ff;color:white;pointer-events:none;animation:turn-fade 1.1s both}@keyframes turn-fade{0%,100%{opacity:0}20%,75%{opacity:1}}
[data-unit="shield"]{color:#0fa7ef!important}[data-unit="virus"]{color:#bf1014!important}[data-unit="drone"],.drone{color:#ffed9a!important}.laser{border-color:#fb8920!important}.magic{border-color:#e870e9!important}
</style>`);

