$('#arena').insertAdjacentHTML('beforeend',`<button id="expandPlayer1" class="expand-player" aria-label="Espandi PLAYER 1">${expandIcon}</button><button id="expandPlayer2" class="expand-player" aria-label="Espandi PLAYER 2">${expandIcon}</button>`);
$('#expandPlayer1').onclick=()=>openPlayerPanel(0);$('#expandPlayer2').onclick=()=>openPlayerPanel(1);
